def ingest(self, seq: int, at: float, pid: int, raw: bytes) -> None:
    if not self._receipt_ready(seq, at, pid, raw):
        return
    if pid in (0x0991, 0x0A0D):
        self._inventory_list(pid, raw)
    elif pid == 0x0ADD:
        self._floor_item(seq, at, raw)
    elif pid == 0x00A1:
        self._floor.pop(int.from_bytes(raw[2:6], "little"), None)
    elif pid == 0x0A37:
        self._pickup(seq, at, raw)
    elif pid in (0x09FD, 0x09FE, 0x09FF):
        self._actor(seq, at, raw)
    else:
        self._other(seq, at, pid, raw)

def _inventory_list(self, pid: int, raw: bytes) -> None:
    error = "Malformed inventory list"
    size = 24 if pid == 0x0991 else 57
    if len(raw) < 4 or int.from_bytes(raw[2:4], "little") != len(raw) or (len(raw) - 4) % size:
        raise ValueError(error)
    pending: dict[int, tuple[int, int]] = {}
    for offset in range(4, len(raw), size):
        index, item = struct.unpack_from("<HH", raw, offset)
        amount = struct.unpack_from("<h", raw, offset + 5)[0] if pid == 0x0991 else 1
        if amount <= 0 or index in pending:
            raise ValueError(error)
        pending[index] = (item, amount)
    self._capacity(len(self._inventory.keys() | pending.keys()), MAX_INVENTORY_SLOTS)
    self._inventory.update(pending)

def encode_equip_request(inventory_index: int, position: int) -> bytes:
    """Represent bytes only, without asserting equip eligibility."""
    _integer(inventory_index, 2, 65535)
    _integer(position, 0, 0xFFFFFFFF)
    return struct.pack("<HHI", 0x0998, inventory_index, position)


def encode_unequip_request(inventory_index: int) -> bytes:
    """Represent bytes only, without asserting ownership or current wear."""
    _integer(inventory_index, 2, 65535)
    return struct.pack("<HH", 0x00AB, inventory_index)


@dataclass(frozen=True, slots=True)
class EquipAcknowledgement:
    inventory_index: int
    wear_location: int
    sprite: int
    raw_result: int
    result: EquipResult | None


def decode_equip_ack(data: bytes) -> EquipAcknowledgement:
    """Decode only; this does not correlate a request or establish ownership."""
    _fixed_frame(data, 0x0999, 11)
    _, index, wear, sprite, raw = struct.unpack("<HHIHB", data)
    _integer(index, 2, 65535)
    result = EquipResult(raw) if raw in (0, 1, 2) else None
    return EquipAcknowledgement(index, wear, sprite, raw, result)
